export interface BannedWordHit {
  word: string     // canonical form, e.g. "shape"
  found: string    // actual token matched, e.g. "shapes"
  sentence: string // full sentence containing the hit
}

interface BannedPattern {
  pattern: RegExp
  word: string
}

// Fixed opener sentences generated by the prompt templates that legitimately
// contain banned words — exempt these exact sentences from the scan.
const OPENER_EXEMPT: RegExp[] = [
  // England/Wales opening style 5: "...has shaped every aspect of my professional development"
  /has shaped every aspect/i,
  // England/Wales opening style 14: "...has shaped how I understand"
  /has shaped how I understand/i,
  // England/Wales opening style 15: "That moment reflects the care I bring"
  /That moment reflects the care/i,
  // Scotland Q2 values opener: "have been shaped by values that mirror"
  /have been shaped by values/i,
  // Scotland 6Cs opener D: "I demonstrate each of the 6 C's through specific"
  /I demonstrate each of the 6/i,
]

// ─── helpers ──────────────────────────────────────────────────────────────────

// Verb stem → inflection pattern. stem is the minimal base; extras for irregular forms.
function v(stem: string, word: string, suffixes: string[] = ['e', 'es', 'ed', 'ing']): BannedPattern {
  const alts = suffixes.join('|')
  return { pattern: new RegExp(`\\b(${stem}(?:${alts}))\\b`, 'i'), word }
}

// Single word — exact, no inflection (adjective/adverb/noun).
function w(word: string): BannedPattern {
  return { pattern: new RegExp(`\\b(${word})\\b`, 'i'), word }
}

// Multi-word phrase — exact, case-insensitive.
function ph(phrase: string): BannedPattern {
  const esc = phrase.replace(/[-]/g, '\\$&')
  return { pattern: new RegExp(`\\b${esc}\\b`, 'i'), word: phrase }
}

