// ─── sentence splitter ────────────────────────────────────────────────────────

function splitSentences(text: string): string[] {
  const sentences: string[] = []
  for (const line of text.split(/\n+/)) {
    const trimmed = line.trim()
    if (!trimmed) continue
    const parts = trimmed.match(/[^.!?]+[.!?]+(?=\s|$)|[^.!?]+$/g) ?? [trimmed]
    for (const part of parts) {
      const s = part.trim()
      if (s.length > 3) sentences.push(s)
    }
  }
  return sentences
}

// ─── public API ───────────────────────────────────────────────────────────────

export function scanBanned(statement: string): BannedWordHit[] {
  const hits: BannedWordHit[] = []
  const seen = new Set<string>()

  for (const sentence of splitSentences(statement)) {
    if (seen.has(sentence)) continue
    if (OPENER_EXEMPT.some(p => p.test(sentence))) continue

    for (const { pattern, word } of BANNED_PATTERNS) {
      const match = sentence.match(pattern)
      if (match) {
        hits.push({ word, found: match[1] ?? match[0], sentence })
        seen.add(sentence)
        break // one hit per sentence — patcher rewrites the whole sentence
      }
    }
  }

  return hits
}
